SELECT c.id, c.post_id, c.member_id, CASE WHEN c.status = 'PUBLISHED' THEN c.content END AS content, c.status, c.created_at
FROM comments c
WHERE c.parent_comment_id = #{parentCommentId} AND c.post_id = #{postId}
ORDER BY c.created_at ASC, c.id ASC LIMIT #{limit}

SELECT c.id, c.post_id, c.member_id, CASE WHEN c.status = 'PUBLISHED' THEN c.content END AS content, c.status, c.created_at
FROM comments c
WHERE c.id = #{commentId}

mapper.update:
UPDATE comments
SET status = 'DELETED'
WHERE id = #{commentId}
AND post_id = #{postId}
AND member_id = #{memberId}
AND status = 'PUBLISHED'
